<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, shallowRef, watch } from 'vue'
import { api, ApiError } from '../api'
import type { KnowledgeCategory } from '../types'
import KnowledgeError from './KnowledgeError.vue'
const props = defineProps<{ spaceId: string; canEdit: boolean; modelValue: string; initialCategories?: KnowledgeCategory[] }>()
const emit = defineEmits<{ 'update:modelValue': [id: string]; denied: [error: ApiError] }>()
const rows = ref<KnowledgeCategory[]>(props.initialCategories || []); const loading = ref(false); const writing = ref(false); const error = shallowRef<ApiError | null>(null); const managing = ref(false); const deleting = ref(false); const form = reactive({ id: '', name: '', parentId: '' })
let generation = 0; let controller: AbortController | undefined
const selected = computed(() => rows.value.find(row => row.id === form.id))
const tree = computed(() => {
  const result: { row: KnowledgeCategory; depth: number }[] = []
  function visit(parentId: string | null, depth: number) { for (const row of rows.value.filter(row => row.parentId === parentId)) { result.push({ row, depth }); if (depth < 5) visit(row.id, depth + 1) } }
  visit(null, 0); return result
})
const parents = computed(() => { const excluded = new Set<string>(form.id ? [form.id] : []); for (let i = 0; i < 5; i++) rows.value.forEach(row => { if (row.parentId && excluded.has(row.parentId)) excluded.add(row.id) }); return tree.value.filter(item => !excluded.has(item.row.id)) })
function fail(failure: unknown) { if (failure instanceof DOMException && failure.name === 'AbortError') return; error.value = failure instanceof ApiError ? failure : new ApiError(0, { title: '分类操作失败，请重试。', status: 0 }); if ([401, 403, 404].includes(error.value.status)) { purge(); emit('denied', error.value) } }
function purge() { generation++; controller?.abort(); rows.value = []; managing.value = false; deleting.value = false; loading.value = false; writing.value = false; Object.assign(form, { id: '', name: '', parentId: '' }) }
async function load() { const own = ++generation; controller?.abort(); controller = new AbortController(); loading.value = true; error.value = null; try { const result = await api.get<KnowledgeCategory[]>(`/knowledge/spaces/${props.spaceId}/categories`, { signal: controller.signal }); if (own === generation) rows.value = result } catch (failure) { if (own === generation) fail(failure) } finally { if (own === generation) loading.value = false } }
async function save() { if (!props.canEdit || writing.value || !form.name.trim()) return; const own = generation; writing.value = true; error.value = null; try { if (selected.value) await api.patch(`/knowledge/categories/${selected.value.id}`, { name: form.name.trim(), parentId: form.parentId || null, version: selected.value.version }); else await api.post(`/knowledge/spaces/${props.spaceId}/categories`, { name: form.name.trim(), parentId: form.parentId || null }); if (own !== generation) return; Object.assign(form, { id: '', name: '', parentId: '' }); await load() } catch (failure) { if (own === generation) fail(failure) } finally { writing.value = false } }
async function remove() { if (!props.canEdit || !selected.value || writing.value) return; const own = generation; const id = selected.value.id; writing.value = true; error.value = null; try { await api.delete(`/knowledge/categories/${id}`, { version: selected.value.version }); if (own !== generation) return; if (props.modelValue === id) emit('update:modelValue', ''); Object.assign(form, { id: '', name: '', parentId: '' }); deleting.value = false; await load() } catch (failure) { if (own === generation) fail(failure) } finally { writing.value = false } }
watch(() => form.id, () => { const row = selected.value; form.name = row?.name || ''; form.parentId = row?.parentId || ''; deleting.value = false })
watch(() => props.canEdit, canEdit => { if (!canEdit) { managing.value = false; deleting.value = false; Object.assign(form, { id: '', name: '', parentId: '' }) } })
onBeforeUnmount(purge); if (!props.initialCategories) void load()
</script>
<template><aside class="knowledge-categories panel" :aria-busy="loading"><div class="panel-header"><h2>知识分类</h2><button v-if="canEdit" type="button" @click="managing = !managing">{{ managing ? '收起管理' : '管理分类' }}</button></div><KnowledgeError :error="error" retry @retry="load" /><p v-if="loading" role="status" class="small muted">正在加载分类…</p><nav aria-label="知识分类"><button type="button" :class="{ selected: !modelValue }" :aria-current="!modelValue ? 'true' : undefined" @click="emit('update:modelValue', '')">全部文档</button><ul class="category-tree"><li v-for="item in tree" :key="item.row.id" :class="`category-depth-${item.depth}`"><button type="button" :aria-current="modelValue === item.row.id ? 'true' : undefined" :class="{ selected: modelValue === item.row.id }" @click="emit('update:modelValue', item.row.id)">{{ item.row.name }}</button></li></ul></nav><p v-if="!loading && !rows.length && !error" class="small muted">暂无分类。</p><form v-if="managing && canEdit" id="category-form" class="form-stack" @submit.prevent="save"><div class="field"><label for="category-edit-id">管理分类</label><select id="category-edit-id" v-model="form.id" :disabled="writing"><option value="">新增分类</option><option v-for="item in tree" :key="item.row.id" :value="item.row.id">{{ '— '.repeat(item.depth) }}{{ item.row.name }}</option></select></div><div class="field"><label for="category-name">分类名称</label><input id="category-name" v-model="form.name" maxlength="160" required :disabled="writing" /></div><div class="field"><label for="category-parent">上级分类</label><select id="category-parent" v-model="form.parentId" :disabled="writing"><option value="">顶级分类</option><option v-for="item in parents" :key="item.row.id" :value="item.row.id">{{ '— '.repeat(item.depth) }}{{ item.row.name }}</option></select></div><el-button native-type="submit" :loading="writing" :disabled="!form.name.trim()">保存分类</el-button><el-button v-if="selected" type="danger" plain :disabled="writing" @click="deleting = !deleting">删除分类</el-button><div v-if="deleting" class="alert warning" role="alert"><p>确认删除“{{ selected?.name }}”？包含子分类或文档的分类不能删除。</p><el-button type="danger" :loading="writing" @click="remove">确认删除分类</el-button><button type="button" @click="deleting = false">取消</button></div></form></aside></template>
